"""Environment settings loader and merger."""
from typing import Dict, Any, List

DEFAULT_CONN_TIMEOUT = 30

def load_system_env() -> Dict[str, Any]:
    return {"timeout": DEFAULT_CONN_TIMEOUT}

def merge_env_settings(base_settings: Dict[str, Any], override_settings: Dict[str, Any]) -> Dict[str, Any]:
    merged = dict(base_settings)
    for key, value in override_settings.items():
        if isinstance(value, dict):
            merged[key] = merge_env_settings(merged.get(key, {}), value)
        elif isinstance(value, list):
            merged[key] = deduplicate_list(merged.get(key, []), value)
        else:
            merged[key] = value
    return merged

def deduplicate_list(base_list: List[Any], override_list: List[Any]) -> List[Any]:
    seen = set()
    result = []
    for item in base_list + override_list:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result
